WITH cleaned AS (SELECT id, method, paid_at, CASE WHEN status = 'REFUNDED' THEN 1 ELSE 0 END AS is_refunded FROM payments WHERE order_id IS NOT NULL), prev_events AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM cleaned), flagged AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '60' DAY THEN 1 ELSE 0 END AS session_start_flag FROM prev_events), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM flagged) SELECT DATE_TRUNC('MONTH', paid_at) AS activity_month, CASE WHEN is_refunded >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_refunded_tier, CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS session_start_flag_tier, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, MAX(prev_paid_at) AS last_seen, PERCENTILE_APPROX(is_refunded, 0.95) AS is_refunded_p95 FROM sessionized GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', paid_at), CASE WHEN is_refunded >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN session_start_flag >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('MONTH', paid_at), CASE WHEN is_refunded >= 82 THEN 'PREMIUM' ELSE 'STANDARD' END), ());
